package com.acme.inventory.config;

import javax.sql.DataSource;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;

/**
 * Connection pools for the inventory service. Credentials come from the
 * environment, injected by the platform at deploy time.
 */
@Configuration
public class DataSourceConfig {

    @Value("${REPORTING_DB_URL}")
    private String reportingUrl;

    @Value("${REPORTING_DB_USER}")
    private String reportingUser;

    @Value("${REPORTING_DB_PASSWORD}")
    private String reportingPassword;

    @Bean
    @Primary
    public DataSource inventoryDataSource(
            @Value("${INVENTORY_DB_URL}") String url,
            @Value("${INVENTORY_DB_USER}") String user,
            @Value("${INVENTORY_DB_PASSWORD}") String password) {
        return pool("inventory", url, user, password, 20, false);
    }

    /** Read-only pool on the reporting replica, used by the nightly stock export. */
    @Bean
    public DataSource reportingDataSource() {
        return pool("reporting", reportingUrl, reportingUser, reportingPassword, 4, true);
    }

    private static DataSource pool(String name, String url, String user, String pass, int size, boolean readOnly) {
        HikariConfig config = new HikariConfig();
        config.setPoolName(name);
        config.setJdbcUrl(url);
        config.setUsername(user);
        config.setPassword(pass);
        config.setMaximumPoolSize(size);
        config.setReadOnly(readOnly);
        return new HikariDataSource(config);
    }
}
